import{_ as l,K as o,a as i,c as p,b as a,k as s,q as r,ac as n}from"./chunks/framework.BSuaGltH.js";const b=JSON.parse('{"title":"五子棋：识别漏防与重复错误","description":"用一次没有补断点的失败复盘，记录威胁、错误应手和改进办法，再做两道自测。","frontmatter":{"title":"五子棋：识别漏防与重复错误","description":"用一次没有补断点的失败复盘，记录威胁、错误应手和改进办法，再做两道自测。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"棋类入门","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"五子棋入门","summary":"用一次没有补断点的失败复盘，记录威胁、错误应手和改进办法，再做两道自测。","status":"active","related":[{"title":"五子棋：自由规则与禁手规则的区别","link":"/life/personal/chess/gomoku/rules","kind":"棋类入门","scope":"general","audience":"general"},{"title":"五子棋：活三、冲四与连续威胁","link":"/life/personal/chess/gomoku/threats","kind":"棋类入门","scope":"general","audience":"general"},{"title":"五子棋：先手、攻防与关键落点","link":"/life/personal/chess/gomoku/attack-defense","kind":"棋类入门","scope":"general","audience":"general"}],"prev":{"text":"五子棋：先手、攻防与关键落点","link":"/life/personal/chess/gomoku/attack-defense"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"五子棋：先手、攻防与关键落点","link":"/life/personal/chess/gomoku/attack-defense"},"next":false},"headers":[],"relativePath":"life/personal/chess/gomoku/review.md","filePath":"life/personal/chess/gomoku/review.md"}'),c={name:"life/personal/chess/gomoku/review.md"},d={class:"chess-example"},h={class:"chess-figure"};function g(u,e,k,m,f,_){const t=o("ArticleImage");return i(),p("div",null,[e[1]||(e[1]=a("h1",{id:"五子棋-识别漏防与重复错误",tabindex:"-1"},[s("五子棋：识别漏防与重复错误 "),a("a",{class:"header-anchor",href:"#五子棋-识别漏防与重复错误","aria-label":'Permalink to "五子棋：识别漏防与重复错误"'},"​")],-1)),e[2]||(e[2]=a("p",null,"五子棋输得快，容易让人觉得“对方突然就连起来了”。复盘要找出那个“不突然”的前兆：上一手是否已经留下唯一成五点？你是不是只看连续四，漏看中间有空格的四？",-1)),e[3]||(e[3]=a("p",null,"本文采用自由练习规则，不包含黑方禁手。坐标 A～O、1～15；所有局部例子的其他位置都不影响当前判断。",-1)),e[4]||(e[4]=a("h2",{id:"一次漏防的全过程",tabindex:"-1"},[s("一次漏防的全过程 "),a("a",{class:"header-anchor",href:"#一次漏防的全过程","aria-label":'Permalink to "一次漏防的全过程"'},"​")],-1)),a("div",d,[a("div",h,[a("p",null,[r(t,{src:"/images/chess/gomoku-review.svg",alt:"漏防之前 · 中间有空格的四。黑走；F8 是白方直接成五点，需先防守。"})])]),e[0]||(e[0]=n(`<div class="chess-explanation"><p>第 8 行白子 D8、E8、G8、H8，中间 F8 为空，轮黑。你看到白没有四颗紧挨着，于是在远处下黑 K10，准备扩大自己的棋形。白接着下 F8，D8～H8 连成五，白胜。</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>列        C D E F G H I</span></span>
<span class="line"><span>黑走之前  . O O . O O .</span></span>
<span class="line"><span>白补 F8   . O O O O O .</span></span></code></pre></div><p>错误不是“K10 永远不好”，而是当时存在更紧急的威胁。黑必须先发现 F8 是白的直接胜点。若黑自己没有立即成五的着法，黑 F8 是消除这条威胁的办法。</p></div>`,1))]),e[5]||(e[5]=n(`<h2 id="回到前一手验证替代方案" tabindex="-1">回到前一手验证替代方案 <a class="header-anchor" href="#回到前一手验证替代方案" aria-label="Permalink to &quot;回到前一手验证替代方案&quot;">​</a></h2><p>把白 F8 和黑 K10 拿回到棋盒，恢复黑走前的局面。改下黑 F8。现在白原先的五点区间变成 <code>OOXOO</code>，不能再靠一个落子连成原来的五。</p><p>这只证明阻止了<strong>这条</strong> 即时威胁，不证明黑已反败为胜。还需检查白的竖线和斜线是否有其他成五点。复盘时把结论写到证据支持的范围，不要把“没立即输”写成“必胜”。</p><h2 id="给失误分类-但不要分得太细" tabindex="-1">给失误分类，但不要分得太细 <a class="header-anchor" href="#给失误分类-但不要分得太细" aria-label="Permalink to &quot;给失误分类，但不要分得太细&quot;">​</a></h2><p>新手先用三类就够：漏看直接成五；看错规则；算漏对手回应。例如漏 F8 是第一类，自由规则和禁手规则混用是第二类，做活四却让对方先成五是第三类。</p><p>同一个错误连续出现两次，就做一个小练习，而不是只写“下次注意”。把对方棋换个方向、换个颜色再摆一次，确认你识别的是结构，而不是记住某个坐标。</p><h2 id="两道自测" tabindex="-1">两道自测 <a class="header-anchor" href="#两道自测" aria-label="Permalink to &quot;两道自测&quot;">​</a></h2><p><strong>题一：</strong> 白 B5、C5、D5、E5，A5 是黑，F5 空，轮黑；黑没有立即成五手。下一步优先哪里？</p><p><strong>答案：F5。</strong> 白只有右端这个直接成五点。黑去别处做三会输给白 F5。</p><p><strong>题二：</strong> 白 B5、C5、D5、E5，A5、F5 都空，轮黑；黑没有立即成五手，也不能以别的方式结束对局。只堵 A5 能救吗？</p><p><strong>答案：不能。</strong> 白下 F5 即胜；堵 F5 则白下 A5。应把复盘位置往前移，寻找为什么让对方做成两端开放的四。输局面里没有万能防守，不要硬找不存在的一手。</p><h2 id="一份五分钟复盘记录" tabindex="-1">一份五分钟复盘记录 <a class="header-anchor" href="#一份五分钟复盘记录" aria-label="Permalink to &quot;一份五分钟复盘记录&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>规则：自由五子棋，五颗及以上获胜</span></span>
<span class="line"><span>局面：白 D8/E8/G8/H8，黑走</span></span>
<span class="line"><span>原着：K10</span></span>
<span class="line"><span>漏看：F8 是直接成五点</span></span>
<span class="line"><span>改着：F8，随后重新检查另外三个方向</span></span>
<span class="line"><span>下盘目标：先找双方的直接胜点，再考虑做三</span></span></code></pre></div><p>每盘保存一张转折局面即可。积累几盘后看自己哪一类失误最多，再决定下一次练“冲四识别”还是“多方向防守”。复盘的目标是形成可重复的检查习惯，不是把每一步都贴上好坏标签。</p><p>规则口径对照：<a href="https://gomoku.renju.net/gomokurules/" target="_blank" rel="noopener noreferrer">RIF 国际 Gomoku 规则</a>。本篇特意采用已声明的自由练习口径，局面与记录均为教学例子。</p>`,15))])}const x=l(c,[["render",g]]);export{b as __pageData,x as default};
